/// Every cursor in the Meridian set, in the order the design's specimen grid lists them.
pub static CURSORS: [Cursor; 12] = [
    Cursor { id: "c-pointer", w: 16, h: 21, off_x: 0, off_y: 0, hot_x: 2, hot_y: 2, argb: &C_POINTER },
    Cursor { id: "c-text", w: 4, h: 16, off_x: 10, off_y: 6, hot_x: 12, hot_y: 14, argb: &C_TEXT },
    Cursor { id: "c-precision", w: 24, h: 24, off_x: 2, off_y: 2, hot_x: 14, hot_y: 14, argb: &C_PRECISION },
    Cursor { id: "c-move", w: 18, h: 18, off_x: 5, off_y: 5, hot_x: 14, hot_y: 14, argb: &C_MOVE },
    Cursor { id: "c-resize-h", w: 16, h: 12, off_x: 6, off_y: 8, hot_x: 14, hot_y: 14, argb: &C_RESIZE_H },
    Cursor { id: "c-resize-v", w: 12, h: 16, off_x: 8, off_y: 6, hot_x: 14, hot_y: 14, argb: &C_RESIZE_V },
    Cursor { id: "c-resize-nwse", w: 16, h: 16, off_x: 6, off_y: 6, hot_x: 14, hot_y: 14, argb: &C_RESIZE_NWSE },
    Cursor { id: "c-resize-nesw", w: 16, h: 16, off_x: 6, off_y: 6, hot_x: 14, hot_y: 14, argb: &C_RESIZE_NESW },
    Cursor { id: "c-grab", w: 18, h: 18, off_x: 5, off_y: 5, hot_x: 14, hot_y: 14, argb: &C_GRAB },
    Cursor { id: "c-grabbing", w: 12, h: 12, off_x: 8, off_y: 8, hot_x: 14, hot_y: 14, argb: &C_GRABBING },
    Cursor { id: "c-working", w: 20, h: 20, off_x: 4, off_y: 4, hot_x: 14, hot_y: 14, argb: &C_WORKING },
    Cursor { id: "c-unavailable", w: 25, h: 25, off_x: 0, off_y: 0, hot_x: 2, hot_y: 2, argb: &C_UNAVAILABLE },
];

/// Look a cursor up by its design-document id.
pub fn find(id: &str) -> Option<&'static Cursor> {
    CURSORS.iter().find(|c| c.id == id)
}
